import{G as e,W as t,n,rt as r}from"./chunks/framework.9o07hMZQ.js";var i=JSON.parse(`{"title":"X-Plane 11/12 Online Flight Tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"en/tutorial/xplane.md","filePath":"en/tutorial/xplane.md","lastUpdated":0}`),a={name:`en/tutorial/xplane.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="x-plane-11-12-online-flight-tutorial" tabindex="-1">X-Plane 11/12 Online Flight Tutorial <a class="header-anchor" href="#x-plane-11-12-online-flight-tutorial" aria-label="Permalink to “X-Plane 11/12 Online Flight Tutorial”">​</a></h1><p>This tutorial covers X-Plane 11 and X-Plane 12, and explains how to connect to the XFLYSIM online flight server.</p><h2 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to “Preparation”">​</a></h2><h3 id="_1-install-the-flight-simulator" tabindex="-1">1. Install the flight simulator <a class="header-anchor" href="#_1-install-the-flight-simulator" aria-label="Permalink to “1. Install the flight simulator”">​</a></h3><ul><li>Purchase and install X-Plane 11 / 12 via Steam or the Laminar Research website.</li><li>It is recommended to update to the latest version to ensure compatibility with the online flight client.</li></ul><h3 id="_2-install-the-online-flight-client" tabindex="-1">2. Install the online flight client <a class="header-anchor" href="#_2-install-the-online-flight-client" aria-label="Permalink to “2. Install the online flight client”">​</a></h3><ul><li>Download and install the XFLYSIM online flight client.</li><li>Enter the account and callsign registered on the online flight website.</li></ul><h3 id="_3-install-the-voice-software" tabindex="-1">3. Install the voice software <a class="header-anchor" href="#_3-install-the-voice-software" aria-label="Permalink to “3. Install the voice software”">​</a></h3><ul><li>Voice crews need to install <strong>XVoice</strong> voice software (see the <a href="/en/tutorial/xvoice.html">XVoice tutorial</a>).</li><li>Text-based crews can skip this step and communicate via text in the game.</li></ul><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to “Connecting”">​</a></h2><ol><li>Launch X-Plane and select the aircraft and airport you want to fly.</li><li>Park the aircraft at a <strong>fixed parking stand</strong> and wait for it to finish loading.</li><li>Start the online flight client, enter your callsign and connect to the server <code>ol.xflysim.com</code>.</li><li>After connecting, submit your flight plan as soon as possible (departure/arrival airports, cruise flight level, planned route, aircraft type, etc.).</li><li>In airspace without ATC services, use the public frequency 122.800; when a controller is online, follow their instructions.</li></ol><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>Connecting directly on taxiways, runways or other non-stand positions is strictly prohibited.</li><li>Please carefully read the <a href="/en/rules.html">User Guidelines</a> before flying.</li><li>In controlled airspace, listen to ATC instructions and observe the &quot;left-window yield principle&quot;.</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};